/**
 * @title A workspace sidebar with page actions in a popover
 * @description Notes-app layout: workspace switcher, quick links with an unread count, favorites, nested workspace pages, and the page's own actions in a popover in the header.
 * @route /notes
 */
import { SidebarInset, SidebarProvider, SidebarTrigger } from "@/components/ui/sidebar";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { AppSidebar } from "@/components/app-sidebar";
import { NavActions } from "@/components/nav-actions";

export default function Page() {
  return (
    <SidebarProvider>
      <AppSidebar />
      <SidebarInset>
        <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 bg-canvas px-4">
          <SidebarTrigger className="-ms-1" />
          <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
          <Breadcrumbs items={[{ label: "Personal life", href: "#" }, { label: "Project management and task tracking" }]} />
          <div className="ms-auto"><NavActions /></div>
        </header>
        <div className="mx-auto flex w-full max-w-3xl flex-1 flex-col gap-4 px-4 py-10">
          <h1 className="text-heading-h1">Project management and task tracking</h1>
          <div aria-hidden className="flex flex-col gap-3">
            {Array.from({ length: 10 }, (_, i) => <div key={i} className="h-4 rounded-sm bg-surface-subtle" style={{ width: `${55 + ((i * 29) % 45)}%` }} />)}
          </div>
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import {
  AudioWaveform, Blocks, Calendar, ChevronRight, Command, FileText, Home, Inbox, MessageCircleQuestion, Search, Settings2, Sparkles, Star, Trash2, type LucideIcon,
} from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  Sidebar, SidebarContent, SidebarGroup, SidebarGroupLabel, SidebarHeader, SidebarMenu, SidebarMenuBadge, SidebarMenuButton, SidebarMenuItem,
  SidebarMenuSub, SidebarMenuSubButton, SidebarMenuSubItem, SidebarRail, useDisclosure,
} from "@/components/ui/sidebar";
import { NavSecondary } from "@/components/nav-secondary";
import { TeamSwitcher } from "@/components/team-switcher";

const teams = [{ name: "Acme Inc", plan: "Enterprise", logo: Command }, { name: "Acme Labs", plan: "Startup", logo: AudioWaveform }];
const quick: { title: string; icon: LucideIcon; isActive?: boolean; badge?: string }[] = [
  { title: "Search", icon: Search }, { title: "Ask AI", icon: Sparkles }, { title: "Home", icon: Home, isActive: true }, { title: "Inbox", icon: Inbox, badge: "10" },
];
const favorites = ["Project management and task tracking", "Family recipe collection", "Fitness tracker and workout routines", "Book notes and reading list", "Travel itinerary"];
const workspaces = [
  { name: "Personal life", pages: ["Daily journal", "Health and wellness", "Personal goals"] },
  { name: "Professional development", pages: ["Career objectives", "Skills acquisition", "Networking contacts"] },
  { name: "Creative projects", pages: ["Writing ideas", "Art and design portfolio", "Music composition"] },
  { name: "Home management", pages: ["Household budget", "Home maintenance", "Family calendar"] },
];
const secondary = [{ title: "Calendar", url: "#", icon: Calendar }, { title: "Settings", url: "#", icon: Settings2 }, { title: "Templates", url: "#", icon: Blocks }, { title: "Trash", url: "#", icon: Trash2 }, { title: "Help", url: "#", icon: MessageCircleQuestion }];

function Workspace({ name, pages }: { name: string; pages: string[] }) {
  const d = useDisclosure(name === "Personal life");
  return (
    <SidebarMenuItem>
      <SidebarMenuButton {...d.triggerProps}>
        <Icon name={ChevronRight} size={16} className={d.open ? "rotate-90 transition-transform" : "transition-transform"} />
        <span>{name}</span>
      </SidebarMenuButton>
      <SidebarMenuSub {...d.contentProps}>
        {pages.map((p) => (
          <SidebarMenuSubItem key={p}>
            <SidebarMenuSubButton href="#"><Icon name={FileText} size={16} className="text-icon-secondary" /><span>{p}</span></SidebarMenuSubButton>
          </SidebarMenuSubItem>
        ))}
      </SidebarMenuSub>
    </SidebarMenuItem>
  );
}

export function AppSidebar() {
  return (
    <Sidebar label="Workspace" className="border-r-0">
      <SidebarHeader>
        <TeamSwitcher teams={teams} />
        <SidebarMenu>
          {quick.map((q) => (
            <SidebarMenuItem key={q.title}>
              <SidebarMenuButton href="#" isActive={q.isActive} size="sm">
                <Icon name={q.icon} size={16} /><span>{q.title}</span>
              </SidebarMenuButton>
              {q.badge && <SidebarMenuBadge label="unread" className="top-1.5">{q.badge}</SidebarMenuBadge>}
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarHeader>
      <SidebarContent>
        <nav aria-label="Pages" className="contents">
          <SidebarGroup>
            <SidebarGroupLabel as="h2">Favorites</SidebarGroupLabel>
            <SidebarMenu>
              {favorites.map((f) => (
                <SidebarMenuItem key={f}>
                  <SidebarMenuButton href="#" size="sm"><Icon name={Star} size={16} /><span>{f}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <SidebarGroup>
            <SidebarGroupLabel as="h2">Workspaces</SidebarGroupLabel>
            <SidebarMenu>{workspaces.map((w) => <Workspace key={w.name} {...w} />)}</SidebarMenu>
          </SidebarGroup>
          <NavSecondary items={secondary} className="mt-auto" />
        </nav>
      </SidebarContent>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import type { LucideIcon } from "lucide-react";
import type { HTMLAttributes } from "react";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupContent, SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Small links near the bottom of the sidebar (support, feedback). */
export function NavSecondary({ items, ...rest }: HTMLAttributes<HTMLDivElement> & { items: { title: string; url: string; icon: LucideIcon }[] }) {
  return (
    <SidebarGroup {...rest}>
      <SidebarGroupContent>
        <SidebarMenu>
          {items.map((item) => (
            <SidebarMenuItem key={item.title}>
              <SidebarMenuButton href={item.url} size="sm" tooltip={item.title}>
                <Icon name={item.icon} size={16} />
                <span>{item.title}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

"use client";
import { useState } from "react";
import { ChevronsUpDown, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

export type Team = { name: string; plan: string; logo: LucideIcon };

/** Workspace switcher at the top of the sidebar. */
export function TeamSwitcher({ teams }: { teams: Team[] }) {
  const { isMobile, state } = useSidebar();
  const [active, setActive] = useState(teams[0]);
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label="Switch workspace"
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "bottom-start"}
          items={[
            ...teams.map((t) => ({ label: t.name, onSelect: () => setActive(t) })),
            { label: "Add workspace", icon: "plus" as const, separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={active.name}>
              <span className="grid size-8 shrink-0 place-items-center rounded-control bg-brand text-fg-on-brand">
                <Icon name={active.logo} size={16} />
              </span>
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{active.name}</span>
                <span className="truncate text-caption-default">{active.plan}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import { useState } from "react";
import { ArrowDown, ArrowUp, Bell, Copy, CornerUpLeft, CornerUpRight, FileText, GalleryVerticalEnd, LineChart, Link, Settings2, Star, Trash, Trash2, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { Popover } from "@/components/ui/overlays";

const groups: { label: string; icon: LucideIcon }[][] = [
  [{ label: "Customize page", icon: Settings2 }, { label: "Turn into wiki", icon: FileText }],
  [{ label: "Copy link", icon: Link }, { label: "Duplicate", icon: Copy }, { label: "Move to", icon: CornerUpRight }, { label: "Move to trash", icon: Trash2 }],
  [{ label: "Undo", icon: CornerUpLeft }, { label: "View analytics", icon: LineChart }, { label: "Version history", icon: GalleryVerticalEnd }, { label: "Show deleted pages", icon: Trash }, { label: "Notifications", icon: Bell }],
  [{ label: "Import", icon: ArrowUp }, { label: "Export", icon: ArrowDown }],
];

/** "Edited …", a star and a popover with the page's actions. */
export function NavActions() {
  const [starred, setStarred] = useState(false);
  return (
    <div className="flex items-center gap-1 text-body-small">
      <span className="me-1 text-fg-secondary max-md:hidden">Edited Oct 8</span>
      <button type="button" aria-pressed={starred} aria-label="Add to favorites" onClick={() => setStarred((s) => !s)}
        className="inline-flex size-8 items-center justify-center rounded-control text-icon-secondary hover:bg-neutral-hover focus-visible:focus-ring">
        <Icon name={Star} size={16} className={starred ? "fill-current text-icon-warning" : ""} />
      </button>
      <Popover
        title="Page actions"
        placement="bottom"
        width={240}
        trigger={({ ref, ...p }) => (
          <button ref={ref} type="button" {...p} aria-label="Page actions" className="inline-flex size-8 items-center justify-center rounded-control text-icon-secondary hover:bg-neutral-hover focus-visible:focus-ring">
            <Icon name="more" size={16} />
          </button>
        )}
      >
        <div className="-mx-2 flex flex-col">
          {groups.map((g, i) => (
            <ul key={i} className="flex flex-col border-line-default py-1 not-first:border-t">
              {g.map((a) => (
                <li key={a.label}>
                  <button type="button" className="flex h-8 w-full items-center gap-2 rounded-sm px-2 text-start text-body-small hover:bg-neutral-hover focus-visible:focus-ring">
                    <Icon name={a.icon} size={16} className="text-icon-secondary" />{a.label}
                  </button>
                </li>
              ))}
            </ul>
          ))}
        </div>
      </Popover>
    </div>
  );
}
